/*
 * Vote Sticker profile pictures, votesticker.org.
 *
 * Pick a state, see every design in every palette, save one as a 1080 px PNG. Everything is drawn
 * on a canvas in the browser; nothing is uploaded. Data: states.js (dates, links) and
 * state-shapes.js (outlines, generated by build/build_shapes.py). Notes: ../README.md.
 *
 * Every design keeps its content inside a 500 px radius of the center. Facebook, Instagram, X and
 * LinkedIn show a profile picture as a circle of 540 px radius on this canvas, so nothing is cut.
 */
(function () {
	'use strict';

	var SIZE = 1080, STORY_H = 1920, SAFE = 500, BADGE_SAFE = 430, RING_R = 506;
	var DISPLAY = '"Vote Display"', DATE = '"Vote Date"';

	var PALETTES = [
		{ id: 'state', name: 'State colors' },
		{ id: 'cream', name: 'Cream and navy', bg: '#FBF8F0', ink: '#14295E', accent: '#C1272D', onAccent: '#FBF8F0' },
		{ id: 'navy', name: 'Navy and red', bg: '#0F2558', ink: '#FBF6E8', accent: '#B3262C', onAccent: '#FBF6E8' },
		{ id: 'forest', name: 'Forest and gold', bg: '#0A3D2C', ink: '#FBF6E8', accent: '#D4AF4A', onAccent: '#0A3D2C' },
		{ id: 'sand', name: 'Sand and rust', bg: '#EBDABF', ink: '#1F1E1C', accent: '#A9552A', onAccent: '#FBF6E8' },
		{ id: 'sky', name: 'Sky and navy', bg: '#D4E8FA', ink: '#14295E', accent: '#C1272D', onAccent: '#FBF8F0' },
		{ id: 'sage', name: 'Sage and forest', bg: '#8FAF88', ink: '#0B3A23', accent: '#E0BC4E', onAccent: '#0B3A23' }
	];
	// Each state's own colors (background, ink, accent): the palettes the ready-made sets were made in,
	// and for the other states the palettes in docs/round3-prompts-one-state.md (October 19).
	var STATE_COLORS = {
		AL: ['#F3ECE1', '#5B1F2B', '#C98B2B'], AK: ['#E6F0F6', '#0E2A47', '#F2B33D'], AZ: ['#FBEBDD', '#2E2A4F', '#D9663B'],
		AR: ['#EEF2E6', '#1F3B2C', '#B5452B'], CA: ['#FFF3E0', '#1F3A5F', '#E07A1F'], CO: ['#1D3557', '#F1FAEE', '#F4B942'],
		CT: ['#EAF0F5', '#13294B', '#5E7F2A'], DE: ['#EAF2F4', '#123C4A', '#C99231'], DC: ['#FFFFFF', '#1B1B1B', '#C8102E'],
		FL: ['#E8F6F3', '#0B4F6C', '#E07A2B'], GA: ['#F6EFE6', '#2B3A2E', '#D2652E'], HI: ['#E5F4F1', '#0D3B4C', '#D9583A'],
		ID: ['#EEF1E8', '#22333B', '#8C6A3F'], IL: ['#EEF2F6', '#14213D', '#D49A12'], IN: ['#F2F0E8', '#1C2541', '#B38F1D'],
		IA: ['#F5F0E1', '#2B2D42', '#C9870F'], KS: ['#F4E9C8', '#1F3A5F', '#D0921A'], KY: ['#EEF3EC', '#123524', '#3A6EA5'],
		LA: ['#EFEDF5', '#2D1E4F', '#C4961F'], ME: ['#E8F1EE', '#123B33', '#3B6EA5'], MD: ['#F6F1E7', '#1C1C1C', '#C98A00'],
		MA: ['#EDF1F5', '#16324F', '#B5502D'], MI: ['#E9F1F7', '#0B3954', '#21857A'], MN: ['#EAF2F8', '#102A43', '#3C8D5A'],
		MS: ['#EEF0EA', '#1F2E2B', '#A8762A'], MO: ['#DCE9F2', '#12355B', '#2E7D6B'], MT: ['#EAF0F4', '#1D3557', '#C46D3B'],
		NE: ['#F4EFE3', '#2C2A29', '#C0392B'], NV: ['#F6EEE6', '#22223B', '#C2703D'], NH: ['#EEF2EE', '#1E3A2F', '#C8553D'],
		NJ: ['#F1ECE2', '#1B2A41', '#B38F1D'], NM: ['#FBF0E1', '#3A2E39', '#D1495B'], NY: ['#1B1B1B', '#FBF6E8', '#F2A900'],
		NC: ['#E6F0F8', '#13294B', '#3B82BF'], ND: ['#F1F2EA', '#203038', '#B38F1D'], OH: ['#F1F1EE', '#1F2A44', '#B33F40'],
		OK: ['#F5EEE6', '#22303C', '#C46A2E'], OR: ['#E6EFE9', '#1F3B2C', '#2F6690'], PA: ['#102A43', '#F0F4F8', '#F0B429'],
		RI: ['#E8F1F6', '#0F3550', '#D0921A'], SC: ['#EAF0F4', '#16324F', '#3E7CB1'], SD: ['#F3EFE5', '#2A2D34', '#4F8271'],
		TN: ['#F3EEE6', '#1F2A44', '#C1663B'], TX: ['#0A3D2C', '#FBF6E8', '#D4AF4A'], UT: ['#FBEFE3', '#2B2D42', '#C8553D'],
		VT: ['#EEF3EC', '#1E3B2C', '#C0392B'], VA: ['#EDE6DA', '#233142', '#8C2F39'], WA: ['#E3EEE6', '#1E4D3A', '#3E7CB1'],
		WV: ['#EEF1EA', '#1F2E3D', '#C4961F'], WI: ['#EEF2F6', '#14213D', '#C9473A'], WY: ['#F2EFE6', '#2B2D42', '#B5652B']
	};
	function paletteFor(id, st) {
		if (id !== 'state') { return PALETTES.filter(function (x) { return x.id === id; })[0] || PALETTES[1]; }
		var c = STATE_COLORS[st.abbr] || ['#0F2558', '#FBF6E8', '#B3262C'];
		// Text on the accent bar takes whichever of the two base colors reads better on it.
		return { id: 'state', name: st.name + ' colors', bg: c[0], ink: c[1], accent: c[2], onAccent: contrast(c[2], c[0]) > contrast(c[2], c[1]) ? c[0] : c[1] };
	}
	// A shade of the background for the square's corners behind a sticker disc: darker on light
	// backgrounds, lighter on dark ones.
	function shade(hex, amt) {
		var n = parseInt(hex.slice(1), 16), dark = luminance(hex) < 0.2;
		return '#' + [n >> 16, (n >> 8) & 255, n & 255].map(function (c) {
			var v = dark ? c + (255 - c) * amt : c * (1 - amt);
			return ('0' + Math.round(v).toString(16)).slice(-2);
		}).join('');
	}
	// Big type first: at 40 to 60 px, the size most people see a profile picture, it reads best (October 19).
	// October 19, evening: Sticker, Poster and Stamp follow the ready-made sets (a disc with rings and a
	// tilted date bar, a two-tone headline, a headline knocked out of a block). "State shape" was retired:
	// it set the headline inside the outline, the pattern rejected from the ChatGPT sets.
	var DESIGNS = [
		{ id: 'sticker', name: 'Sticker' },
		{ id: 'poster', name: 'Poster' },
		{ id: 'stamp', name: 'Stamp' },
		{ id: 'type', name: 'Big type' },
		{ id: 'badge', name: 'Badge' }
	];
	// Short lines only, at most 10 characters each (POR CORREO), so a card reads at 40 px in a comment thread
	// (Garrett, October 19; QA enforces the limit).
	// `early` headlines only where a verified row has early voting, `mail` only in all-mail states;
	// everywhere else the card says VOTE NOV 3.
	var HEADLINES = {
		early: { early: true, label: 'Vote early', lines: ['VOTE', 'EARLY'] },
		mail: { mail: true, label: 'Vote by mail', lines: ['VOTE', 'BY MAIL'] },
		nov3: { dated: true, label: 'Vote Nov 3', lines: ['VOTE', 'NOV 3'] },
		// "I voted" is the main alternate to the state's own message (Garrett, October 19): true for anyone
		// who has voted, any state, any day.
		// Its date bar names the state and year instead of a date.
		ivoted: { label: 'I voted', lines: ['I VOTED'], stateLine: true },
		mailed: { mail: true, label: 'I voted by mail', lines: ['I VOTED', 'BY MAIL'], stateLine: true },
		voted: { early: true, label: 'I voted early', lines: ['I VOTED', 'EARLY'] },
		// Spanish (October 19): tú, per the project glossary (docs/spanish-style.md); "Ya voté" is the
		// everyday Mexican phrasing for "I voted". Date bars
		// put the day first ("19–30 OCT", "HASTA EL 27 OCT").
		votatemprano: { early: true, es: true, label: 'Vota temprano (español)', lines: ['VOTA', 'TEMPRANO'] },
		votacorreo: { mail: true, es: true, label: 'Vota por correo (español)', lines: ['VOTA', 'POR CORREO'] },
		vota3nov: { dated: true, es: true, label: 'Vota 3 de nov (español)', lines: ['VOTA', '3 DE NOV'] },
		yavote: { es: true, label: 'Ya voté (español)', lines: ['YA VOTÉ'], stateLine: true },
		yavotetemprano: { early: true, es: true, label: 'Ya voté temprano (español)', lines: ['YA VOTÉ', 'TEMPRANO'] },
		yavotecorreo: { mail: true, es: true, label: 'Ya voté por correo (español)', lines: ['YA VOTÉ', 'POR CORREO'], stateLine: true },
		voyavotar: { es: true, label: 'Voy a votar (español)', lines: ['VOY A', 'VOTAR'], stateLine: true },
	};

	// Language (October 19): the page sets VOTE_LANG and VOTE_T (maker strings from the same dictionary as
	// the page, i18n/es.php). T('English %s', value) returns the translation with values filled in.
	var LANG = window.VOTE_LANG || 'en';
	function T(key) {
		var out = (window.VOTE_T || {})[key] || key, args = Array.prototype.slice.call(arguments, 1);
		return out.replace(/%s/g, function () { return args.length ? String(args.shift()) : ''; });
	}
	// A state's name in the page language (Spanish names come from the page's VOTE_META).
	function nameOf(st) { return ((window.VOTE_META || {})[st.abbr] || {}).name || st.name; }

	function hasEarly(st) { return st.status === 'verified' && st.kind !== 'none'; }
	function headlinesFor(st) {
		var keys = Object.keys(HEADLINES).filter(function (k) {
			var h = HEADLINES[k];
			return (!h.early || hasEarly(st)) && (!h.mail || (hasEarly(st) && st.kind === 'mail'));
		});
		// Spanish pages list the Spanish messages first.
		return LANG === 'es' ? keys.filter(function (k) { return HEADLINES[k].es; }).concat(keys.filter(function (k) { return !HEADLINES[k].es; })) : keys;
	}
	// The state's own message (VOTE EARLY, VOTE BY MAIL, VOTE NOV 3): share images and the ready-made sets.
	function stateHeadline(st) { return !hasEarly(st) ? 'nov3' : st.kind === 'mail' ? 'mail' : 'early'; }
	function defaultHeadline(st) {
		var k = stateHeadline(st);
		return LANG === 'es' ? { early: 'votatemprano', mail: 'votacorreo', nov3: 'vota3nov' }[k] : k;
	}
	function headlineLines(key, st) {
		var h = HEADLINES[key] || HEADLINES.nov3;
		return typeof h.lines === 'function' ? h.lines(st) : h.lines;
	}
	var MONTHS = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];
	var MONTHS_LONG = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
	var DAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

	var ELECTION = window.VOTE_ELECTION, STATES = window.VOTE_STATES, SHAPES = window.VOTE_SHAPES;
	var byAbbr = {};
	STATES.forEach(function (s) { byAbbr[s.abbr] = s; });

	/* ------------------------------------------------------------------ */
	/* Small helpers                                                       */
	/* ------------------------------------------------------------------ */
	function $(id) { return document.getElementById(id); }
	function esc(s) { return String(s).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); }
	function load(key, fallback) { try { var v = localStorage.getItem('vote-cards:' + key); return v ? JSON.parse(v) : fallback; } catch (e) { return fallback; } }
	function save(key, value) { try { localStorage.setItem('vote-cards:' + key, JSON.stringify(value)); } catch (e) { /* private window */ } }

	function day(iso) { var p = iso.split('-'); return new Date(+p[0], +p[1] - 1, +p[2]); }
	function shortDate(d) { return MONTHS[d.getMonth()] + ' ' + d.getDate(); }
	function longDate(d) { return DAYS[d.getDay()] + ', ' + MONTHS_LONG[d.getMonth()] + ' ' + d.getDate(); }
	function slug(name) { return name.toLowerCase().replace(/[^a-z]+/g, '-'); }

	// "OCT 19–30", or "OCT 24–NOV 1" across a month.
	function rangeLine(a, b) {
		if (a.getMonth() === b.getMonth()) { return MONTHS[a.getMonth()] + ' ' + a.getDate() + '–' + b.getDate(); }
		return shortDate(a) + '–' + shortDate(b);
	}

	function electionLine() { return DAYS[day(ELECTION.day).getDay()].toUpperCase() + ' ' + shortDate(day(ELECTION.day)); }

	// The date line a state's cards start with. Only verified rows show early voting dates.
	// The date line a card starts with, for a state and headline. A headline that already carries the
	// date (VOTE NOV 3) gets ELECTION DAY under it.
	function defaultDateLine(st, headline) {
		var hd = headline && HEADLINES[headline];
		if (hd && hd.es && !hd.stateLine) { return spanishDateLine(st, hd); }
		if (hd && hd.dated) { return 'ELECTION DAY'; }
		// Short enough to read in a thumbnail: the name up to 10 letters, else the postal code (NC 2026).
		if (headline && HEADLINES[headline] && HEADLINES[headline].stateLine) { var nm = HEADLINES[headline].es ? nameOf(st) : st.name; return (nm.length <= 10 ? nm.toUpperCase() : st.abbr) + ' ' + ELECTION.day.slice(0, 4); }
		if (!hasEarly(st)) { return electionLine(); }
		if (st.dateLine) { return st.dateLine; }
		if (st.kind === 'mail') { return 'DUE ' + shortDate(day(st.end)); }
		if (!st.start || !st.end) { return electionLine(); }
		return rangeLine(day(st.start), day(st.end));
	}

	// Spanish date bars: day before month, "HASTA EL" for a last day.
	var MESES = { JAN: 'ENE', APR: 'ABR', AUG: 'AGO', SEP: 'SEPT', DEC: 'DIC' };
	function mes(d) { var m = MONTHS[d.getMonth()]; return MESES[m] || m; }
	function spanishDateLine(st, hd) {
		if (hd.dated || !hasEarly(st)) { return 'DÍA DE LAS ELECCIONES'; }
		if (st.kind === 'mail') { return 'HASTA EL ' + day(st.end).getDate() + ' ' + mes(day(st.end)); }
		var by = /^BY ([A-Z]{3}) (\d+)$/.exec(st.dateLine || '');
		if (by) { return 'HASTA EL ' + by[2] + ' ' + (MESES[by[1]] || by[1]); }
		if (!st.start || !st.end) { return 'DÍA DE LAS ELECCIONES'; }
		var a = day(st.start), b = day(st.end);
		return a.getMonth() === b.getMonth() ? a.getDate() + '–' + b.getDate() + ' ' + mes(b) : a.getDate() + ' ' + mes(a) + '–' + b.getDate() + ' ' + mes(b);
	}

	function luminance(hex) {
		var n = parseInt(hex.slice(1), 16);
		return [n >> 16, (n >> 8) & 255, n & 255].map(function (c) {
			c /= 255; return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
		}).reduce(function (sum, c, i) { return sum + c * [0.2126, 0.7152, 0.0722][i]; }, 0);
	}
	function contrast(a, b) { var x = luminance(a), y = luminance(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); }

	/* ------------------------------------------------------------------ */
	/* State outlines                                                      */
	/* ------------------------------------------------------------------ */
	var shapeCache = {};
	function shape(abbr) {
		if (shapeCache[abbr]) { return shapeCache[abbr]; }
		var s = SHAPES[abbr];
		var pts = [];
		s.d.replace(/(-?\d+),(-?\d+)/g, function (m, x, y) { pts.push([+x, +y]); return m; });
		return (shapeCache[abbr] = { w: s.w, h: s.h, cap: s.cap, path: new Path2D(s.d), pts: pts });
	}

	/* ------------------------------------------------------------------ */
	/* Layout: each design returns items in its own units, then fit()       */
	/* scales and centers them so every point sits inside the safe circle.  */
	/* ------------------------------------------------------------------ */
	var measureCtx = document.createElement('canvas').getContext('2d');

	// Text sized so its widest line's ink is `width` wide, capped at `maxAsc` tall.
	function textBlock(lines, family, width, maxAsc) {
		measureCtx.font = '200px ' + family;
		measureCtx.textBaseline = 'alphabetic';
		var ms = lines.map(function (l) { return measureCtx.measureText(l); });
		var widest = Math.max.apply(null, ms.map(function (m) { return m.actualBoundingBoxLeft + m.actualBoundingBoxRight; }));
		var asc = Math.max.apply(null, ms.map(function (m) { return m.actualBoundingBoxAscent; }));
		var k = width / widest;
		if (maxAsc && asc * k > maxAsc) { k = maxAsc / asc; }
		return {
			family: family, size: 200 * k, asc: asc * k, gap: asc * k * 0.12,
			lines: lines.map(function (l, i) {
				var m = ms[i];
				return { s: l, w: (m.actualBoundingBoxLeft + m.actualBoundingBoxRight) * k, left: m.actualBoundingBoxLeft * k };
			})
		};
	}

	// Place a text block centered on cx with its top at `top`. Returns the items and the bottom.
	function placeText(block, cx, top, color) {
		var items = [], y = top;
		block.lines.forEach(function (l, i) {
			if (i) { y += block.gap; }
			var base = y + block.asc;
			items.push({ t: 'text', s: l.s, font: block.size + 'px ' + block.family, color: color,
				x: cx - l.w / 2 + l.left, base: base, box: [cx - l.w / 2, y, cx + l.w / 2, base] });
			y = base;
		});
		return { items: items, bottom: y };
	}

	function iconItem(st, cx, top, h, maxW, color, star) {
		var sh = shape(st.abbr), k = Math.min(h / sh.h, maxW / sh.w);
		var w = sh.w * k, x = cx - w / 2;
		var items = [{ t: 'shape', abbr: st.abbr, x: x, y: top, k: k, color: color }];
		if (star) { items.push({ t: 'star', cx: x + sh.cap[0] * k, cy: top + sh.cap[1] * k, r: Math.max(sh.w, sh.h) * k * 0.09, color: star }); }
		return { items: items, bottom: top + sh.h * k };
	}

	function dateItems(text, cx, top, width, maxAsc, color, boxColor) {
		var block = textBlock([text], DATE, width, maxAsc);
		if (!boxColor) { return placeText(block, cx, top, color); }
		var padY = block.asc * 0.34, padX = block.asc * 0.5;
		var placed = placeText(block, cx, top + padY, color);
		var w = block.lines[0].w;
		placed.items.unshift({ t: 'box', box: [cx - w / 2 - padX, top, cx + w / 2 + padX, placed.bottom + padY], color: boxColor });
		placed.bottom += padY;
		return placed;
	}

	// Tip a group of items about the center of its first item's box (radians).
	function tilt(items, rot) {
		var b = items[0].box, pv = [(b[0] + b[2]) / 2, (b[1] + b[3]) / 2];
		items.forEach(function (it) { it.rot = rot; it.pivot = pv; });
	}

	var LAYOUTS = {
		// The ready-made look: a disc with a heavy ring and a thin inner ring, the state on top, a big
		// headline, and the dates on an accent bar tipped a few degrees, like a sticker slapped on.
		sticker: function (st, p, lines, dateText) {
			var icon = iconItem(st, 0, 0, 200, 360, p.ink, p.accent);
			var head = textBlock(lines, DISPLAY, 800, 300);
			var placed = placeText(head, 0, icon.bottom + 40, p.ink);
			var date = dateItems(dateText, 0, placed.bottom + head.asc * 0.26, 640, Math.min(head.asc * 0.5, 120), p.onAccent, p.accent);
			tilt(date.items, -0.05);
			return { items: icon.items.concat(placed.items, date.items), safe: 420, disc: { fill: p.bg, outer: shade(p.bg, 0.16), rings: [[506, 16, p.ink], [470, 4, p.ink]] } };
		},
		// Two-tone poster: the first line in ink, the second in the accent when it reads, dates between rules.
		poster: function (st, p, lines, dateText) {
			var icon = iconItem(st, 0, 0, 190, 340, p.ink, p.accent);
			var head = textBlock(lines, DISPLAY, 820, 300);
			var placed = placeText(head, 0, icon.bottom + 40, p.ink);
			if (lines.length > 1 && contrast(p.accent, p.bg) >= 3) { placed.items[placed.items.length - 1].color = p.accent; }
			var date = dateItems(dateText, 0, placed.bottom + head.asc * 0.34, 600, Math.min(head.asc * 0.44, 110), p.ink);
			var db = date.items[0].box, cy = (db[1] + db[3]) / 2, rw = 70, gap = 26, th = Math.max(6, (db[3] - db[1]) * 0.12);
			var rules = [
				{ t: 'box', box: [db[0] - gap - rw, cy - th / 2, db[0] - gap, cy + th / 2], color: p.ink },
				{ t: 'box', box: [db[2] + gap, cy - th / 2, db[2] + gap + rw, cy + th / 2], color: p.ink }
			];
			return { items: icon.items.concat(placed.items, date.items, rules), safe: SAFE };
		},
		// Stamp: the headline knocked out of a solid ink block with rounded corners, the state above.
		stamp: function (st, p, lines, dateText) {
			var icon = iconItem(st, 0, 0, 180, 320, p.ink, p.accent);
			var head = textBlock(lines, DISPLAY, 700, 280);
			var padX = head.asc * 0.32, padY = head.asc * 0.26;
			var placed = placeText(head, 0, icon.bottom + 34 + padY, p.bg);
			var w = Math.max.apply(null, head.lines.map(function (l) { return l.w; }));
			var block = { t: 'box', box: [-w / 2 - padX, icon.bottom + 34, w / 2 + padX, placed.bottom + padY], color: p.ink, radius: head.asc * 0.22 };
			var date = dateItems(dateText, 0, block.box[3] + head.asc * 0.28, w + padX * 2, head.asc * 0.42, contrast(p.accent, p.bg) >= 3 ? p.accent : p.ink);
			return { items: icon.items.concat([block], placed.items, date.items), safe: SAFE };
		},
		// A small state on top, the headline as big as it goes, dates in the accent color.
		type: function (st, p, lines, dateText) {
			var icon = iconItem(st, 0, 0, 120, 220, p.ink, p.accent);
			var head = textBlock(lines, DISPLAY, 760);
			var placed = placeText(head, 0, icon.bottom + 44, p.ink);
			var plain = contrast(p.accent, p.bg) >= 3;
			var date = dateItems(dateText, 0, placed.bottom + head.asc * 0.22, plain ? 760 : 680, head.asc * (plain ? 0.78 : 0.62),
				plain ? p.accent : p.onAccent, plain ? null : p.accent);
			return { items: icon.items.concat(placed.items, date.items), safe: SAFE };
		},
		// A ring at the edge of the circle crop, the state, the headline, dates on an accent bar.
		badge: function (st, p, lines, dateText) {
			var icon = iconItem(st, 0, 0, 110, 200, p.ink, p.accent);
			var head = textBlock(lines, DISPLAY, 640);
			var placed = placeText(head, 0, icon.bottom + 36, p.ink);
			var date = dateItems(dateText, 0, placed.bottom + head.asc * 0.2, 520, head.asc * 0.42, p.onAccent, p.accent);
			return { items: icon.items.concat(placed.items, date.items), safe: BADGE_SAFE, ring: p.ink };
		}
	};

	function itemPoints(it) {
		if (it.t === 'shape') {
			return shape(it.abbr).pts.map(function (q) { return [it.x + q[0] * it.k, it.y + q[1] * it.k]; });
		}
		var b = it.t === 'star' ? [it.cx - it.r, it.cy - it.r, it.cx + it.r, it.cy + it.r] : it.box;
		var pts = [[b[0], b[1]], [b[2], b[1]], [b[0], b[3]], [b[2], b[3]]];
		if (!it.rot) { return pts; }
		var c = Math.cos(it.rot), s = Math.sin(it.rot), pv = it.pivot;
		return pts.map(function (q) { var dx = q[0] - pv[0], dy = q[1] - pv[1]; return [pv[0] + dx * c - dy * s, pv[1] + dx * s + dy * c]; });
	}

	// Scale and center so the farthest point of any item lands on the safe circle.
	function fit(layout) {
		var pts = [];
		layout.items.forEach(function (it) { pts = pts.concat(itemPoints(it)); });
		var xs = pts.map(function (q) { return q[0]; }), ys = pts.map(function (q) { return q[1]; });
		var cx = (Math.min.apply(null, xs) + Math.max.apply(null, xs)) / 2;
		var cy = (Math.min.apply(null, ys) + Math.max.apply(null, ys)) / 2;
		var far = Math.max.apply(null, pts.map(function (q) { return Math.hypot(q[0] - cx, q[1] - cy); }));
		return { s: layout.safe / far, cx: cx, cy: cy, far: far };
	}

	/* ------------------------------------------------------------------ */
	/* Drawing                                                             */
	/* ------------------------------------------------------------------ */
	function drawStar(ctx, cx, cy, r) {
		ctx.beginPath();
		for (var i = 0; i < 10; i++) {
			var a = -Math.PI / 2 + i * Math.PI / 5, rr = i % 2 ? r * 0.42 : r;
			ctx.lineTo(cx + Math.cos(a) * rr, cy + Math.sin(a) * rr);
		}
		ctx.closePath();
		ctx.fill();
	}

	function drawShape(ctx, it) {
		ctx.save();
		ctx.translate(it.x, it.y);
		ctx.scale(it.k, it.k);
		ctx.fill(shape(it.abbr).path);
		ctx.restore();
	}

	function drawItem(ctx, it) {
		if (it.rot) {
			ctx.save();
			ctx.translate(it.pivot[0], it.pivot[1]);
			ctx.rotate(it.rot);
			ctx.translate(-it.pivot[0], -it.pivot[1]);
			drawItem(ctx, { t: it.t, s: it.s, font: it.font, color: it.color, x: it.x, base: it.base, box: it.box, radius: it.radius, stroke: it.stroke, strokeWidth: it.strokeWidth });
			ctx.restore();
			return;
		}
		ctx.fillStyle = it.color;
		if (it.t === 'shape') { drawShape(ctx, it); return; }
		if (it.t === 'star') { drawStar(ctx, it.cx, it.cy, it.r); return; }
		if (it.t === 'box') {
			ctx.beginPath();
			if (it.radius && ctx.roundRect) { ctx.roundRect(it.box[0], it.box[1], it.box[2] - it.box[0], it.box[3] - it.box[1], it.radius); } else { ctx.rect(it.box[0], it.box[1], it.box[2] - it.box[0], it.box[3] - it.box[1]); }
			ctx.fill();
			return;
		}
		ctx.font = it.font;
		ctx.textBaseline = 'alphabetic';
		ctx.textAlign = 'left';
		if (it.stroke) {
			// Background-colored letters with an ink outline: over the state the outline melts into
			// the fill, outside it the letter is outlined, so a ragged coastline never cuts a letter.
			ctx.lineJoin = 'round';
			ctx.lineWidth = it.strokeWidth;
			ctx.strokeStyle = it.stroke;
			ctx.strokeText(it.s, it.x, it.base);
		}
		ctx.fillText(it.s, it.x, it.base);
	}

	// Draw one card on a canvas `px` pixels wide: square, or a 9:16 Story with the same card in the
	// middle. No site address on any image (Garrett, October 19).
	function render(canvas, px, opts) {
		var st = byAbbr[opts.state], p = paletteFor(opts.palette, st);
		var layout = LAYOUTS[opts.design](st, p, headlineLines(opts.headline, st), opts.dateText);
		var f = fit(layout);
		var tall = opts.story ? STORY_H : SIZE;
		canvas.width = px;
		canvas.height = Math.round(px * tall / SIZE);
		var ctx = canvas.getContext('2d');
		ctx.setTransform(px / SIZE, 0, 0, px / SIZE, 0, 0);
		ctx.fillStyle = layout.disc ? layout.disc.outer : p.bg;
		ctx.fillRect(0, 0, SIZE, tall);
		if (opts.story) {
			ctx.translate(0, (tall - SIZE) / 2);
		}
		if (layout.disc) {
			// The disc fills the profile-picture circle exactly; the corners outside it never show once cropped.
			ctx.fillStyle = layout.disc.fill;
			ctx.beginPath();
			ctx.arc(SIZE / 2, SIZE / 2, SIZE / 2, 0, Math.PI * 2);
			ctx.fill();
			layout.disc.rings.forEach(function (r) {
				ctx.strokeStyle = r[2];
				ctx.lineWidth = r[1];
				ctx.beginPath();
				ctx.arc(SIZE / 2, SIZE / 2, r[0], 0, Math.PI * 2);
				ctx.stroke();
			});
		}
		if (layout.ring) {
			ctx.strokeStyle = layout.ring;
			ctx.lineWidth = 12;
			ctx.beginPath();
			ctx.arc(SIZE / 2, SIZE / 2, RING_R, 0, Math.PI * 2);
			ctx.stroke();
		}
		if (opts.decorOnly) { return fit(layout); }
		ctx.translate(SIZE / 2, SIZE / 2);
		ctx.scale(f.s, f.s);
		ctx.translate(-f.cx, -f.cy);
		layout.items.forEach(function (it) { drawItem(ctx, it); });
		return f;
	}

	/* ------------------------------------------------------------------ */
	/* Saving: the Softball Austin card maker's rules, by device           */
	/* ------------------------------------------------------------------ */
	var DEVICE = (function () {
		var ua = navigator.userAgent || '';
		if (/iPhone|iPad|iPod/i.test(ua) || (/Macintosh/i.test(ua) && (navigator.maxTouchPoints || 0) > 1)) { return 'ios'; }
		if (/Android/i.test(ua)) { return 'android'; }
		return 'desktop';
	})();
	var SHARE_TO_PHOTOS = (function () {
		if (DEVICE !== 'ios') { return false; }
		try {
			var probe = new File([new Blob(['x'], { type: 'image/png' })], 'probe.png', { type: 'image/png' });
			return !!navigator.canShare && navigator.canShare({ files: [probe] });
		} catch (e) { return false; }
	})();
	var TIPS = {
		ios: SHARE_TO_PHOTOS ? T('Tap Save to Photos, then Save Image. Then set it as your profile picture from Photos.') : T('Tap Open image, press and hold the picture, and choose Save to Photos.'),
		android: T('The picture saves to your Downloads. Set it as your profile picture from there.'),
		desktop: T('The picture saves to your Downloads folder.')
	};

	var current = { blob: null, url: null, name: '' };
	function wireSave(link) {
		link.addEventListener('click', function (e) {
			if (!current.blob) { e.preventDefault(); return; }
			if (!SHARE_TO_PHOTOS) { return; }
			e.preventDefault();
			var file = new File([current.blob], current.name, { type: 'image/png' });
			navigator.share({ files: [file] }).catch(function (err) {
				// Closing the share sheet is not an error; anything else falls back to the download.
				if (err && err.name === 'AbortError') { return; }
				window.location.href = current.url;
			});
		});
	}

	/* ------------------------------------------------------------------ */
	/* Page                                                                */
	/* ------------------------------------------------------------------ */
	var state = {
		state: null,
		headline: 'nov3',
		dateEdited: false,
		design: load('design2', 'sticker'),
		palette: load('palette2', 'state'),
		dateText: '',
		circle: load('circle', true),
		story: false
	};
	var previewSeq = 0;

	function opts() {
		return { state: state.state, design: state.design, palette: state.palette, headline: state.headline, dateText: state.dateText.toUpperCase() };
	}

	// The state panel and suggested post text are rendered by index.php in the page's language (October 19);
	// this script no longer rebuilds them.

	function buildGrid() {
		var grid = $('grid');
		grid.innerHTML = '';
		DESIGNS.forEach(function (d) {
			PALETTES.forEach(function (p) {
				var b = document.createElement('button');
				b.type = 'button';
				b.className = 'tile';
				b.dataset.design = d.id;
				b.dataset.palette = p.id;
				b.setAttribute('aria-label', T(d.name) + ', ' + T(p.name));
				b.setAttribute('aria-pressed', String(d.id === state.design && p.id === state.palette));
				var c = document.createElement('canvas');
				b.appendChild(c);
				grid.appendChild(b);
			});
		});
	}

	function drawGrid() {
		var px = Math.round(Math.min(window.devicePixelRatio || 1, 2) * 180);
		Array.prototype.forEach.call(document.querySelectorAll('#grid .tile'), function (b) {
			var o = opts();
			o.design = b.dataset.design;
			o.palette = b.dataset.palette;
			render(b.querySelector('canvas'), px, o);
		});
	}

	function drawPreview() {
		var seq = ++previewSeq;
		var canvas = document.createElement('canvas');
		var o = opts();
		o.story = state.story;
		render(canvas, SIZE, o);
		var link = $('save');
		link.setAttribute('aria-disabled', 'true');
		canvas.toBlob(function (blob) {
			if (seq !== previewSeq || !blob) { return; }
			if (current.url) { URL.revokeObjectURL(current.url); }
			current.blob = blob;
			current.url = URL.createObjectURL(blob);
			current.name = 'vote-early-' + state.state.toLowerCase() + '-' + state.design + '-' + state.palette + (state.story ? '-story' : '') + '.png';
			$('preview').src = current.url;
			link.href = current.url;
			link.download = current.name;
			$('open').href = current.url;
			link.removeAttribute('aria-disabled');
		}, 'image/png');
	}

	function setPressed() {
		Array.prototype.forEach.call(document.querySelectorAll('#grid .tile'), function (b) {
			b.setAttribute('aria-pressed', String(b.dataset.design === state.design && b.dataset.palette === state.palette));
		});
	}

	function showState(abbr, keepDate) {
		var st = byAbbr[abbr];
		if (!st) { $('maker').hidden = true; return; }
		state.state = abbr;
		// Each state starts on its own headline; the menu lists only the ones true for it.
		var headSel = $('headline');
		headSel.innerHTML = '';
		headlinesFor(st).forEach(function (k) {
			var o = document.createElement('option');
			o.value = k;
			o.textContent = T(HEADLINES[k].label);
			headSel.appendChild(o);
		});
		if (!keepDate || headlinesFor(st).indexOf(state.headline) < 0) { state.headline = defaultHeadline(st); }
		headSel.value = state.headline;
		if (!keepDate) { state.dateText = defaultDateLine(st, state.headline); state.dateEdited = false; }
		$('date').value = state.dateText;
		var lead = $('info').querySelector('b');
		var plain = st.status === 'verified' && lead ? lead.textContent + ' ' + T('Official info: ') + st.officialLabel : nameOf(st) + ': ' + T('Election Day is %s.', T(ELECTION.label));
		$('summary').textContent = plain;
		setAlt();
		showGallery(st);
		$('maker').hidden = false;
		drawGrid();
		drawPreview();
	}

	// Hand-made pictures for the state, listed by index.php from assets/states/<abbr>/.
	function showGallery(st) {
		var files = (window.VOTE_GALLERY || {})[st.abbr] || [];
		$('gallery').hidden = !files.length;
		// States with ready-made pictures lead with them; the maker follows as "Or Make Your Own" (October 19).
		$('gallery-h').textContent = T('Ready-Made %s Stickers', nameOf(st));
		var first = !files.length;
		$('maker-h').textContent = first ? T('Make Your %s Sticker', nameOf(st)) : T('Or Make Your Own');
		$('maker-h').classList.toggle('maker-h--first', first);
		document.body.classList.toggle('has-gallery', !!files.length);
		var grid = $('gallery-grid');
		grid.innerHTML = '';
		grid.style.setProperty('--cols', files.length <= 6 ? Math.max(files.length, 1) : files.length <= 8 ? 4 : 5);
		files.forEach(function (src, i) {
			var name = 'vote-' + st.abbr.toLowerCase() + '-' + (i + 1) + '.jpg';
			var a = document.createElement('a');
			a.className = 'tile';
			a.href = src;
			a.download = name;
			var img = document.createElement('img');
			img.src = src;
			img.alt = T('%s vote picture, hand-made design %s', nameOf(st), i + 1);
			img.width = img.height = 1080;
			img.loading = 'lazy';
			a.appendChild(img);
			grid.appendChild(a);
		});
	}

	function setAlt() {
		var st = byAbbr[state.state];
		$('preview').alt = T('Profile picture: ') + headlineLines(state.headline, st).join(' ') + ', ' + nameOf(st) + '. ' + $('summary').textContent;
	}

	function redraw() { drawGrid(); drawPreview(); }

	// Language choice: an explicit click on English/Español is remembered in this browser. The English
	// home page suggests Spanish once to a browser that prefers it; nothing ever redirects.
	function language() {
		var get = function () { try { return localStorage.getItem('vote-sticker:lang'); } catch (e) { return null; } };
		var set = function (v) { try { localStorage.setItem('vote-sticker:lang', v); } catch (e) { /* private window */ } };
		Array.prototype.forEach.call(document.querySelectorAll('[data-lang-choice]'), function (a) {
			a.addEventListener('click', function () { set(a.getAttribute('data-lang-choice')); });
		});
		var bar = $('lang-suggest');
		if (!bar) { return; }
		var langs = navigator.languages && navigator.languages.length ? navigator.languages : [navigator.language || ''];
		if (!get() && /^es\b/i.test(langs[0] || '')) { bar.hidden = false; }
		$('lang-suggest-no').addEventListener('click', function () { set('en'); bar.hidden = true; });
	}

	// Spanish pages: the header and showcase art become Spanish stickers drawn here (the ready-made sets
	// are English images).
	function spanishArt() {
		if (LANG !== 'es') { return; }
		Array.prototype.forEach.call(document.querySelectorAll('img[data-es-state]'), function (img) {
			var st = byAbbr[img.getAttribute('data-es-state')];
			if (!st) { return; }
			var c = document.createElement('canvas'), h = defaultHeadline(st);
			render(c, 720, { state: st.abbr, design: 'sticker', palette: 'state', headline: h, dateText: defaultDateLine(st, h) });
			img.src = c.toDataURL('image/png');
			img.removeAttribute('loading');
		});
	}

	function init() {
		language();
		spanishArt();
		finder();
		var headSel = $('headline');
		$('circle').checked = state.circle;
		document.body.classList.toggle('as-circle', state.circle);
		$('tip').textContent = TIPS[DEVICE];
		$('save').textContent = SHARE_TO_PHOTOS ? T('Save to Photos') : T('Download picture');
		wireSave($('save'));
		buildGrid();

		headSel.addEventListener('change', function () {
			state.headline = headSel.value;
			// The date line follows the headline until someone types their own.
			if (!state.dateEdited) { state.dateText = defaultDateLine(byAbbr[state.state], state.headline); $('date').value = state.dateText; }
			setAlt();
			redraw();
		});
		$('date').addEventListener('input', function () { state.dateText = $('date').value; state.dateEdited = true; redraw(); });
		$('date-reset').addEventListener('click', function () { showState(state.state); });
		Array.prototype.forEach.call(document.querySelectorAll('[data-size]'), function (b) {
			b.addEventListener('click', function () {
				state.story = b.dataset.size === 'story';
				Array.prototype.forEach.call(document.querySelectorAll('[data-size]'), function (x) { x.setAttribute('aria-pressed', String(x === b)); });
				document.body.classList.toggle('is-story', state.story);
				drawPreview();
			});
		});
		$('circle').addEventListener('change', function () {
			state.circle = $('circle').checked;
			save('circle', state.circle);
			document.body.classList.toggle('as-circle', state.circle);
		});
		$('grid').addEventListener('click', function (e) {
			var b = e.target.closest('.tile');
			if (!b) { return; }
			state.design = b.dataset.design;
			state.palette = b.dataset.palette;
			save('design2', state.design);
			save('palette2', state.palette);
			setPressed();
			drawPreview();
			var top = $('preview').getBoundingClientRect().top;
			if (top < 0 || top > window.innerHeight * 0.6) { $('preview-wrap').scrollIntoView({ behavior: 'smooth', block: 'start' }); }
		});
		$('copy').addEventListener('click', function () {
			var t = $('post-text');
			var done = function () { $('copy').textContent = T('Copied'); setTimeout(function () { $('copy').textContent = T('Copy post text'); }, 2000); };
			if (navigator.clipboard && navigator.clipboard.writeText) {
				navigator.clipboard.writeText(t.value).then(done, function () { t.select(); document.execCommand('copy'); done(); });
			} else { t.select(); document.execCommand('copy'); done(); }
		});

		// Copy this page's link (its own share image and title go with it). Phones that can share get
		// the share sheet instead; the clipboard is the fallback everywhere.
		var shareBtn = $('share-link');
		if (shareBtn) {
			var shareUrl = shareBtn.dataset.url, shareTitle = shareBtn.dataset.title, shareLabel = $('share-label').textContent;
			var said = function (t) { $('share-label').textContent = t; setTimeout(function () { $('share-label').textContent = shareLabel; }, 2200); };
			shareBtn.addEventListener('click', function () {
				if (navigator.share && /Android|iPhone|iPad/.test(navigator.userAgent)) {
					navigator.share({ title: shareTitle, url: shareUrl }).catch(function () {});
					return;
				}
				var copied = function () { said(T('Link copied')); };
				var fallback = function () {
					var t = document.createElement('textarea');
					t.value = shareUrl; t.setAttribute('readonly', ''); t.style.position = 'fixed'; t.style.left = '-9999px';
					document.body.appendChild(t); t.select();
					try { document.execCommand('copy'); copied(); } catch (e) { said(T('Copy this: ') + shareUrl); }
					document.body.removeChild(t);
				};
				if (navigator.clipboard && navigator.clipboard.writeText) { navigator.clipboard.writeText(shareUrl).then(copied, fallback); } else { fallback(); }
			});
		}

		// Each state has its own page (/<slug>/, rendered by index.php); the menu goes there.
		var start = window.VOTE_PAGE_STATE;
		if (byAbbr[start]) { showState(start); }
	}

	// The state finder: a type-ahead combobox (ARIA 1.2 pattern). Names match from the start of any word,
	// two letters also match the postal code ("tx"), and choosing a state goes to its page.
	function finder() {
		var input = $('state-find'), list = $('state-options'), go = $('state-go');
		if (!input) { return; }
		var meta = window.VOTE_META || {}, matches = [], active = -1;
		var visit = function (abbr) { if (meta[abbr]) { window.location.href = (window.VOTE_BASE || '/') + meta[abbr].slug + '/'; } };
		// Accent-free matching, on the page-language name and the English name ("nueva", "new", "nuev").
		var fold = function (x) { return x.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z ]/g, ''); };
		var find = function (q) {
			q = fold(q.trim());
			if (!q) { return []; }
			var code = q.length === 2 ? STATES.filter(function (s) { return s.abbr.toLowerCase() === q; }) : [];
			var words = STATES.filter(function (s) {
				return [nameOf(s), s.name].some(function (nm) { var n = fold(nm); return n.indexOf(q) === 0 || n.indexOf(' ' + q) > 0; });
			});
			return code.concat(words.filter(function (s) { return code.indexOf(s) < 0; })).slice(0, 8);
		};
		var close = function () { list.hidden = true; input.setAttribute('aria-expanded', 'false'); input.removeAttribute('aria-activedescendant'); active = -1; };
		var mark = function (i) {
			active = i;
			Array.prototype.forEach.call(list.children, function (li, k) { li.setAttribute('aria-selected', String(k === i)); });
			if (i >= 0) { input.setAttribute('aria-activedescendant', 'state-opt-' + i); } else { input.removeAttribute('aria-activedescendant'); }
		};
		var draw = function () {
			matches = find(input.value);
			list.innerHTML = '';
			matches.forEach(function (s, i) {
				var li = document.createElement('li');
				li.id = 'state-opt-' + i;
				li.setAttribute('role', 'option');
				li.setAttribute('aria-selected', 'false');
				var nm = document.createElement('span');
				nm.textContent = nameOf(s);
				var st = document.createElement('span');
				st.className = 'finder__status';
				st.textContent = (meta[s.abbr] || {}).status || '';
				li.appendChild(nm);
				li.appendChild(st);
				li.addEventListener('mousedown', function (e) { e.preventDefault(); visit(s.abbr); });
				list.appendChild(li);
			});
			if (!matches.length && input.value.trim()) {
				var none = document.createElement('li');
				none.className = 'finder__none';
				none.textContent = T('No state matches. Try the full name.');
				list.appendChild(none);
			}
			var open = !!input.value.trim();
			list.hidden = !open;
			input.setAttribute('aria-expanded', String(open && matches.length > 0));
			mark(matches.length ? 0 : -1);
		};
		input.addEventListener('input', draw);
		input.addEventListener('keydown', function (e) {
			if (e.key === 'ArrowDown' && matches.length) { e.preventDefault(); if (list.hidden) { draw(); } else { mark(Math.min(active + 1, matches.length - 1)); } }
			else if (e.key === 'ArrowUp' && matches.length) { e.preventDefault(); mark(Math.max(active - 1, 0)); }
			else if (e.key === 'Enter') { e.preventDefault(); if (matches[active]) { visit(matches[active].abbr); } else if (matches[0]) { visit(matches[0].abbr); } }
			else if (e.key === 'Escape') { close(); }
		});
		input.addEventListener('blur', function () { setTimeout(close, 120); });
		go.addEventListener('click', function () { draw(); if (matches[0]) { visit(matches[active >= 0 ? active : 0].abbr); } else { input.focus(); } });
	}

	function fonts() {
		var base = (window.VOTE_ASSETS || 'assets/') + 'fonts/';
		return Promise.all([
			new FontFace(DISPLAY.replace(/"/g, ''), 'url(' + base + 'anton.woff2)'),
			new FontFace(DATE.replace(/"/g, ''), 'url(' + base + 'archivo-black.woff2)')
		].map(function (f) { return f.load().then(function (l) { document.fonts.add(l); }); }));
	}

	// For the QA script: draw any card and report how far its content reaches from the center.
	window.VOTE_CARDS = { stateHeadline: stateHeadline, paletteFor: paletteFor, render: render, fit: fit, LAYOUTS: LAYOUTS, PALETTES: PALETTES, DESIGNS: DESIGNS, HEADLINES: HEADLINES, headlinesFor: headlinesFor, defaultHeadline: defaultHeadline, defaultDateLine: defaultDateLine, SAFE: SAFE };

	fonts().then(init, function () { init(); });
})();
